 async function execute(){setBusy(true);setError('');setNotice('');if(category==='codes')setCodeResult(null);if(operation==='capture'){shortcutCapture.current=true;notifyDesktopCapture('captureStarted');}try{const options=batchFilters?batchImageFilters(values,inputs.length):taskOptions(task,values);if(operation==='capture'&&values.monitor===undefined)options.monitor=health?.os==='Windows'?0:-1;if(operation==='image_split'){if(values.xCuts)options.xCuts=values.xCuts;if(values.yCuts)options.yCuts=values.yCuts;}if(operation==='video_gif')options.ranges=validClipRanges(clipRanges);if(operation==='pdf_manage'&&pdfOrder.length){options.page_order=pdfOrder;options.rotations=pdfRotations;}if(operation==='pdf_split')options.mode=options.pages?'selected':'groups';if(operation==='web_capture'){if(!browserReady)throw Error('nativeUnavailable');const response=await client.captureBrowser(String(options.format),options.split===true,String(options.url??''));if(response.job){updateJob(response.job);if(tracker.current)await tracker.current.wait(response.job);}else throw Error('processingFailed');}else{const ids=operation==='code_generate'&&options.kind==='qr'&&qrLogo?[qrLogo.file.id]:inputs.map(item=>item.id);if(operation==='code_generate'&&options.kind==='qr'&&qrLogo)Object.assign(options,{logoInput:0,logo_shape:qrLogo.shape});const job=await run(operation,ids,options);if(category==='codes')setCodeResult(job);if(operation==='capture'){const image=job.result?.files?.find(file=>file.mime?.startsWith('image/'));if(!image)throw Error('processingFailed');editResult(image,true);notifyDesktopCapture('captureReady');}}}catch(value){if(operation==='capture')finishDesktopCaptureSession(shortcutCapture,'captureCancelled');if(value instanceof Error&&value.message==='cancelled')setError('');else catchError(value);}finally{setBusy(false);}}
 async function saveCanvas(edits:CanvasEdits){setBusy(true);try{if(operation==='signature_apply'&&!inputs[0]){await saveSignature(edits);return;}const options=taskOptions(task,values),ids=inputs.map(item=>item.id);if(operation==='pdf_annotate'&&pdfCanvas&&inputs[0]){const blob=await edits.overlay(),overlay=await client.upload(new File([blob],'annotation.png',{type:'image/png'}));const job=await run('pdf_annotate',[inputs[0].id,overlay.id],{page:pdfCanvas.page,previewWidth:edits.width,previewHeight:edits.height}),result=job.result?.files?.find(file=>file.mime==='application/pdf');if(result){setInputs(current=>[result,...current.slice(1)]);setPdfCanvas(null);}return;}if(operation==='image_retouch'){options.strokes=edits.strokes;options.rectangles=edits.layers.filter(layer=>layer.type==='rect').map(layer=>[layer.x,layer.y,layer.width,layer.height]);}else if(operation==='image_background'){options.strokes=edits.strokes;if(inputs[1])options.backgroundInput=1;}else if(operation==='image_mosaic')options.regions=edits.regions;else if(operation==='signature_apply'){const overlay=await client.upload(new File([await edits.overlay()],'signature.png',{type:'image/png'}));options.signatureInput=ids.length;ids.push(overlay.id);if(!inputs[0]?.name.toLowerCase().endsWith('.docx'))Object.assign(options,{overlay:true,previewWidth:edits.width,previewHeight:edits.height});}else if(operation==='canvas_export'){Object.assign(options,{width:edits.width,height:edits.height,pages:edits.pages});}else{options.layers=edits.layers;options.baseCount=1;if(edits.crop)options.crop=edits.crop;}const result=await run(operation,ids,options);if(captureEditorId&&operation==='image_edit')captureImageResult(result);}finally{setBusy(false);}}
 async function search(searchQuery=query,filters:FileSearchFilters={}){searchController.current?.abort();const controller=new AbortController(),revision=++searchRevision.current;searchController.current=controller;setSearching(true);setQuery(searchQuery);setError('');try{const result=await client.search(searchQuery,filters,controller.signal);if(revision===searchRevision.current){setSearchFiles(result.files);setSelected([]);setRenamePreview(null);}}catch(value){if(!controller.signal.aborted&&revision===searchRevision.current)catchError(value);}finally{if(revision===searchRevision.current)setSearching(false);}}
