 function editResult(file:AgentFile,captureSession=false){setCaptureEditorId(captureSession?file.id:null);setCategory(file.mime==='application/pdf'?'pdf':'image');setOperation(file.mime==='application/pdf'?'pdf_manage':'image_edit');setInputs([file]);setValues({});setPdfCanvas(null);setError('');}
 async function recordAction(action:RecordingAction|'toggle',options:Record<string,unknown>={}){
  if(nativeState.current.busy||!nativeState.current.paired)return null;
  setError('');
  try{return await recordingGate.current.run(action,options,{health:()=>client.health(),execute:(command,args)=>run(command,[],args),onHealth:setHealth,onBusy:value=>{nativeState.current.busy=value;setBusy(value);}});}
  catch(value){if(!(value instanceof Error&&value.message==='cancelled')){catchError(value);notifyDesktopCapture('shortcutError');}return null;}
 }
